<?php get_header(); ?>
<main id="main">
  <?php while (have_posts()) : the_post(); $type = get_post_type_object(get_post_type()); ?>
    <div class="page-intro"><div class="wrap"><?php if (!in_array(get_post_type(), array('isg_product', 'isg_service'), true)) { isg_breadcrumbs(); } ?><span class="eyebrow"><?php echo esc_html($type ? $type->labels->singular_name : __('Article', 'isg')); ?></span><h1><?php the_title(); ?></h1><?php if (has_excerpt()) : ?><p><?php echo esc_html(get_the_excerpt()); ?></p><?php endif; ?></div></div>
    <?php if (in_array(get_post_type(), array('isg_product', 'isg_service'), true)) : ?><div class="detail-sticky"><div class="wrap"><?php isg_breadcrumbs(); ?><div class="detail-sticky-row"><nav class="tabs detail-tabs" data-detail-nav aria-label="<?php esc_attr_e('On this page', 'isg'); ?>"></nav><?php $linked_shop = (int) get_post_meta(get_the_ID(), '_isg_shop_product_id', true); $linked_shop = $linked_shop && get_post_status($linked_shop) === 'publish' ? $linked_shop : 0; ?><a class="btn blue" href="<?php echo esc_url($linked_shop ? get_permalink($linked_shop) : 'mailto:' . get_theme_mod('isg_sales_email', 'sales@isg.dev') . '?subject=' . rawurlencode(get_the_title() . ' inquiry')); ?>"><?php echo $linked_shop ? esc_html__('Buy', 'isg') : esc_html__('Contact sales', 'isg'); ?></a></div></div></div><?php endif; ?>
    <div class="wrap">
      <article class="detail-hero"><div class="visual"><?php if (has_post_thumbnail()) : the_post_thumbnail('large', array('alt' => get_the_title())); else : ?><img src="<?php echo esc_url(get_template_directory_uri() . '/assets/logo.png'); ?>" alt=""><?php endif; ?></div><div><span class="eyebrow"><?php echo esc_html($type ? $type->labels->singular_name : 'ISG'); ?></span><h2><?php the_title(); ?></h2><p><?php echo esc_html(get_the_excerpt()); ?></p><div class="actions"><?php $external = get_post_meta(get_the_ID(), '_isg_external_url', true); if ($external) : ?><a class="btn blue" href="<?php echo esc_url($external); ?>" target="_blank" rel="noopener"><?php echo get_post_type() === 'isg_download' ? esc_html__('Download', 'isg') : esc_html__('Open resource', 'isg'); ?><?php if (get_post_type() === 'isg_download') : $size = get_post_meta(get_the_ID(), '_isg_file_size', true); $format = get_post_meta(get_the_ID(), '_isg_file_type', true); echo ' · ' . esc_html(trim($format . ' ' . $size)); endif; ?></a><?php endif; ?><a class="btn outline" href="mailto:<?php echo esc_attr(get_theme_mod('isg_sales_email', 'sales@isg.dev')); ?>?subject=<?php echo rawurlencode(get_the_title() . ' inquiry'); ?>"><?php esc_html_e('Contact sales', 'isg'); ?></a></div></div></article>
      <div class="entry-content" data-detail-content><?php the_content(); ?></div>
      <?php if (get_post_type() === 'isg_product') :
          $product_id = get_the_ID();
          $shop_id = (int) get_post_meta($product_id, '_isg_shop_product_id', true);
          $shop_product = $shop_id && function_exists('wc_get_product') ? wc_get_product($shop_id) : false;
          $cases = get_posts(array('post_type' => 'isg_case', 'post_status' => 'publish', 'numberposts' => 12, 'meta_key' => '_isg_related_product', 'meta_value' => $product_id));
          $documents = get_posts(array('post_type' => 'isg_download', 'post_status' => 'publish', 'numberposts' => -1, 'meta_key' => '_isg_related_product', 'meta_value' => $product_id));
      ?>
        <?php if ($cases) : ?><section class="detail-section"><div class="section-head"><h2><?php esc_html_e('Implementations', 'isg'); ?></h2><div class="carousel-actions"><button type="button" class="icon-btn" data-carousel-prev aria-label="<?php esc_attr_e('Previous implementation', 'isg'); ?>">&#8592;</button><button type="button" class="icon-btn" data-carousel-next aria-label="<?php esc_attr_e('Next implementation', 'isg'); ?>">&#8594;</button></div></div><div class="case-carousel" data-case-carousel><?php foreach ($cases as $case) : get_template_part('template-parts/card', null, array('post' => $case)); endforeach; ?></div></section><?php endif; ?>
        <?php if ($documents) : ?><section class="detail-section"><h2><?php esc_html_e('Product documents', 'isg'); ?></h2><div class="download-grid"><?php foreach ($documents as $document) : $file = get_post_meta($document->ID, '_isg_external_url', true); $type = get_post_meta($document->ID, '_isg_file_type', true); $size = get_post_meta($document->ID, '_isg_file_size', true); ?><article class="download-item"><div><span class="card-kicker"><?php echo esc_html($type ?: __('File', 'isg')); ?></span><h3><?php echo esc_html(get_the_title($document)); ?></h3></div><small><?php echo esc_html(trim($type . ' ' . $size)); ?></small><a class="text-link" href="<?php echo esc_url($file ?: get_permalink($document)); ?>" <?php echo $file ? 'target="_blank" rel="noopener"' : ''; ?>><?php esc_html_e('Download', 'isg'); ?> &#8595;</a></article><?php endforeach; ?></div></section><?php endif; ?>
        <?php if ($documents) : $project_terms = get_the_terms($documents[0]->ID, 'isg_download_project'); if ($project_terms && !is_wp_error($project_terms)) : ?><p class="detail-all-downloads"><a class="text-link" href="<?php echo esc_url(add_query_arg('project', $project_terms[0]->slug, isg_archive_link('isg_download'))); ?>"><?php esc_html_e('All product downloads', 'isg'); ?> &#8594;</a></p><?php endif; endif; ?>
        <?php if ($shop_product && $shop_product->is_visible()) : ?><section class="detail-section"><h2><?php esc_html_e('Buy this product', 'isg'); ?></h2><p class="lead"><?php echo wp_kses_post($shop_product->get_price_html()); ?></p><a class="btn blue" href="<?php echo esc_url(get_permalink($shop_id)); ?>"><?php esc_html_e('View in shop', 'isg'); ?></a></section><?php endif; ?>
      <?php endif; ?>
      <?php if (get_post_type() === 'isg_product' || get_post_type() === 'isg_service') : ?><section class="detail-section"><h2><?php esc_html_e('Discuss your project', 'isg'); ?></h2><p class="lead"><?php esc_html_e('Tell us what you need and the ISG team will suggest a suitable solution.', 'isg'); ?></p><a class="btn blue" href="mailto:<?php echo esc_attr(get_theme_mod('isg_sales_email', 'sales@isg.dev')); ?>?subject=<?php echo rawurlencode(get_the_title() . ' inquiry'); ?>"><?php esc_html_e('Contact sales', 'isg'); ?></a></section><?php endif; ?>
    </div>
  <?php endwhile; ?>
</main>
<?php get_footer(); ?>
